import type { CommerceScene, Composition } from "@still-shift/scene-contract";
import {
  createCompositionPreview,
  type CompositionResources,
} from "../../packages/renderer-core/src/composition/render/renderer.ts";
import { passageDiagnostics } from "../../packages/renderer-core/src/passage-diagnostics.ts";

/** Extra inputs exercise the same full-frame parity loop without modifying CE0 fixtures. */
export function commerceTextVariants(id: string, source: CommerceScene) {
  const variants: { id: string; scene: CommerceScene }[] = [];
  if (id === "component/commerce-text-fit") {
    const scene = structuredClone(source);
    if (scene.componentData?.schemaVersion !== "scene-components-3")
      throw new Error("Expected relationship components");
    scene.textFits = scene.componentData.textFits.map((fit) => ({
      ...fit,
      padding: 24,
    }));
    scene.componentData.textFits = [];
    const node = scene.nodes.find((node) => node.id === "timing__caption")!;
    if (node.type !== "text") throw new Error("Expected caption");
    scene.componentData.states = scene.componentData.states.filter(
      (state) => state.target !== node.id,
    );
    node.align = "right";
    node.rotation = -7;
    node.states = [
      "รายละเอียดเล็กน้อยสำหรับทุกวัน",
      "ภาพเดิมในมุมมองที่แตกต่างกัน",
    ];
    node.text = node.states[0]!;
    variants.push({ id: `${id}/native-thai`, scene });
  }
  if (id === "component/commerce-value") {
    for (const rounding of ["half-away-from-zero", "truncate"] as const) {
      const scene = structuredClone(source);
      const data = scene.componentData!;
      const value = data.values[0]!;
      value.range = [-2000, 2000];
      value.from = -1234.01;
      value.to = -1233.98;
      const binding = data.bindings.find((binding) => binding.kind === "text")!;
      if (binding.kind !== "text") throw new Error("Expected numeric binding");
      binding.format = {
        decimals: 2,
        rounding,
        decimalSeparator: ",",
        groupSeparator: ".",
        prefix: "€",
        suffix: " total",
      };
      const node = scene.nodes.find((node) => node.id === binding.target)!;
      if (node.type !== "text") throw new Error("Expected numeric text");
      node.align = "center";
      node.parent = "subject-a";
      node.x = -200;
      node.y = 450;
      node.rotation = 5;
      variants.push({ id: `${id}/${rounding}`, scene });
    }
  }
  return variants;
}

/** Invalid exported payloads must fail during preparation, before any frame is drawn. */
export function assertCommerceTextPreparation(
  composition: Composition,
  resources: CompositionResources,
) {
  const index = composition.layers.findIndex(
    (layer) =>
      layer.type === "provider" && layer.provider === "commerce.text@1.1.0",
  );
  if (index < 0) return 0;
  type Provider = Extract<Composition["layers"][number], { type: "provider" }>;
  const reject = (mutate: (layer: Provider) => void, expected: string) => {
    const input = structuredClone(composition);
    mutate(input.layers[index] as Provider);
    let error: unknown;
    const canvas = document.createElement("canvas");
    try {
      createCompositionPreview(canvas, input, resources).dispose();
    } catch (caught) {
      error = caught;
    } finally {
      canvas.width = canvas.height = 0;
    }
    if (
      !error ||
      !passageDiagnostics(error).some(
        (d) => d.code === expected || d.message.includes(expected),
      )
    )
      throw new Error(
        `Expected preparation failure ${expected}: ${JSON.stringify(passageDiagnostics(error))}`,
      );
  };
  reject((layer) => {
    layer.assets = [];
  }, "comp-provider-asset");
  reject((layer) => {
    layer.provider = "commerce.text@1.0.0";
  }, "comp-provider-params");
  const layer = composition.layers[index] as Provider;
  if (layer.params.fit) {
    reject((layer) => {
      layer.params.fit = { minSize: 60, maxSize: 32 };
    }, "comp-provider-params");
    reject((layer) => {
      const node = layer.params.node as { width: number };
      node.width = 1;
    }, "Text cannot fit at minimum size");
  } else {
    reject((layer) => {
      const numeric = layer.params.numeric as { samples: string[] };
      numeric.samples = ["not a formatted value"];
    }, "comp-provider-params");
    reject((layer) => {
      // The unsampled endpoint must still overflow, as it does on the family path.
      const node = layer.params.node as {
        width: number;
        fontSize: number;
        fontAsset: string;
        textBox: { maxLines: number };
      };
      const font = resources.fonts.get(node.fontAsset)!;
      const ctx = document.createElement("canvas").getContext("2d")!;
      ctx.font = `${font.weight} ${node.fontSize}px "${font.family}"`;
      const metrics = ctx.measureText("9");
      node.width =
        Math.max(
          metrics.width,
          metrics.actualBoundingBoxLeft + metrics.actualBoundingBoxRight,
        ) + 0.1;
      node.textBox.maxLines = 1;
      layer.params.numeric = {
        value: {
          id: "overflow",
          range: [0, 10],
          from: 9,
          to: 10,
          window: { start: 0, end: 1, easing: "linear" },
        },
        format: {
          decimals: 0,
          rounding: "truncate",
          decimalSeparator: ".",
          groupSeparator: "",
          prefix: "",
          suffix: "",
        },
        samples: ["9"],
      };
    }, "text-overflow");
  }
  return 4;
}

tests/helpers/composition-commerce-geome.source:
import {
  PreparedNodeSchema,
  type CommerceScene,
} from "@still-shift/scene-contract";

/** Exercise coordinate spaces and stroke styles beyond the unchanged CE0 fixtures. */
export function commerceGeometryVariants(id: string, source: CommerceScene) {
  if (id === "commerce/atom-attachment") {
    const scene = structuredClone(source);
    const art = scene.nodes.find((node) => node.id === "product-art")!;
    const path = scene.nodes.find((node) => node.id === "attached-line")!;
    if (art.type !== "image" || path.type !== "path")
      throw new Error("Expected attachment nodes");
    art.states[0]!.crop = [300, 0, 700, 600];
    scene.geometry![0]!.protectedRegions = [];
    scene.geometry![0]!.anchors.left = [420, 150];
    scene.attachments![0]!.offset = [7, -4];
    scene.attachments!.push({
      path: path.id,
      endpoint: "start",
      source: art.id,
      anchor: "left",
      offset: [-12, 9],
      protect: true,
    });
    Object.assign(path, {
      parent: "path-plane",
      x: 12,
      y: -8,
      width: 100,
      height: 80,
      rotation: -11,
      lineStyle: "brush",
      endArrow: true,
    });
    scene.nodes.push(
      PreparedNodeSchema.parse({
        id: "path-plane",
        type: "group",
        x: 35,
        y: 42,
        width: 400,
        height: 400,
        rotation: 21,
      }),
    );
    scene.events.push(
      {
        node: "product",
        property: "rotation",
        start: 0,
        end: 239,
        from: 8,
        to: 18,
        easing: "linear",
      },
      {
        node: "path-plane",
        property: "scaleX",
        start: 0,
        end: 180,
        from: 1,
        to: 1.1,
        easing: "smoothstep",
      },
      {
        node: path.id,
        property: "reveal",
        start: 0,
        end: 100,
        from: 0,
        to: 1,
        easing: "linear",
      },
    );
    return [{ id: `${id}/nested-crop-brush`, scene }];
  }
  if (id === "component/commerce-leader") {
    const scene = structuredClone(source);
    const art = scene.nodes.find((node) => node.id === "subject-art")!;
    const path = scene.nodes.find((node) => node.id === "annotation__line")!;
    if (art.type !== "image" || path.type !== "path")
      throw new Error("Expected annotation nodes");
    art.states[0]!.crop = [300, 0, 700, 600];
    scene.nodes.find((node) => node.id === "subject-a")!.rotation = 12;
    scene.componentData!.annotations[0]!.points[1] = {
      node: art.id,
      point: [561, 168.24],
      space: "source",
      offset: [9, 3],
    };
    Object.assign(path, {
      x: 13,
      y: -9,
      width: 300,
      height: 200,
      rotation: -6,
      lineStyle: "ink",
      endArrow: true,
    });
    return [{ id: `${id}/source-crop-ink`, scene }];
  }
  return [];
}

tests/helpers/composition-commerce-masks.source:
import {
  PreparedNodeSchema,
  type CommerceScene,
} from "@still-shift/scene-contract";

/** Check group flattening, shared alpha sources and visibility beyond the CE0 samples. */
export function commerceMaskVariants(id: string, source: CommerceScene) {
  if (id !== "commerce/atom-matte") return [];
  const inverted = structuredClone(source);
  inverted.mattes![0]!.invert = true;
  const product = inverted.nodes.find((node) => node.id === "product")!;
  product.opacity = 0.65;
  product.rotation = 13;
  if (product.type === "group") product.clip = true;
  inverted.nodes.find((node) => node.id === "alpha-mask")!.opacity = 0.6;
  const art = inverted.nodes.find((node) => node.id === "product-art")!;
  inverted.nodes.push({ ...art, id: "overlap", x: 35, opacity: 0.7 });

  const shared = structuredClone(source);
  const index = shared.nodes.findIndex((node) => node.id === "alpha-mask");
  const mask = shared.nodes[index]!;
  if (mask.type !== "image") throw new Error("Expected image matte");
  shared.nodes[index] = PreparedNodeSchema.parse({
    id: mask.id,
    x: mask.x,
    y: mask.y,
    width: mask.width,
    height: mask.height,
    origin: mask.origin,
    type: "group",
    rotation: 9,
    opacity: 0.55,
    clip: true,
  });
  shared.nodes.push({
    ...mask,
    id: "alpha-image",
    parent: mask.id,
    x: 0,
    y: 0,
  });
  shared.nodes.push({
    ...mask,
    id: "alpha-overlap",
    parent: mask.id,
    x: 75,
    y: 20,
    opacity: 0.5,
  });
  shared.visibility = [{ target: mask.id, start: 20, end: 200 }];
  const target = shared.nodes.find((node) => node.id === "product")!;
  const image = shared.nodes.find((node) => node.id === "product-art")!;
  shared.nodes.push({ ...target, id: "second", x: 60, opacity: 0.6 });
  shared.nodes.push({ ...image, id: "second-art", parent: "second" });
  shared.mattes!.push({
    ...shared.mattes![0]!,
    target: "second",
    invert: true,
  });
  return [
    { id: `${id}/inverted-overlap`, scene: inverted },
    { id: `${id}/shared-group-source`, scene: shared },
  ];
}

