import {
  PreparedNodeSchema,
  ComponentDataSchema,
  type CommerceScene,
  type StoryScene,
} from "@still-shift/scene-contract";

export function motionPathVariants<T extends CommerceScene | StoryScene>(
  id: string,
  source: T,
): { id: string; scene: T }[] {
  if (!["commerce/atom-path", "component/story-leader"].includes(id)) return [];
  return ["spatial", "morph", "spatial-morph"].map((kind) => {
    const scene = structuredClone(source);
    scene.motionModel = "curves-1";
    const node = scene.nodes.find((node) => node.type === "path")!;
    if (node.type !== "path") throw new Error("Expected path");
    node.lineStyle =
      kind === "morph" ? "brush" : kind === "spatial-morph" ? "ink" : "uniform";
    node.lineWidth = 9;
    if (kind !== "morph")
      scene.spatialPaths = [
        {
          node: node.id,
          segments: [
            [
              [200, 450],
              [300, 100],
              [600, 950],
              [820, 490],
            ],
          ],
        },
      ];
    if (kind !== "spatial")
      scene.pathMorphs = [
        {
          node: node.id,
          keys: [
            {
              frame: 0,
              points: [
                [220, 780],
                [540, 780],
                [820, 490],
              ],
            },
            {
              frame: 75,
              points: [
                [240, 420],
                [640, 180],
                [860, 710],
              ],
              easing: "in-out-cubic",
            },
            {
              frame: 150,
              points: [
                [200, 580],
                [540, 330],
                [820, 490],
              ],
              easing: "out-cubic",
            },
          ],
        },
      ];
    scene.nodes.push(
      PreparedNodeSchema.parse({
        id: "follower",
        type: "rect",
        width: 40,
        height: 30,
        radius: 5,
        fill: "#ad523d",
      }),
    );
    scene.signals = [
      {
        id: "path-progress",
        keys: [
          { frame: 0, value: 0 },
          { frame: 170, value: 1 },
        ],
      },
    ];
    scene.constraints = [
      {
        type: "follow-path",
        target: "follower",
        path: node.id,
        progress: "path-progress",
        orient: "tangent",
      },
    ];
    if (scene.schemaVersion === "story-scene-1") {
      scene.flows = [
        {
          id: "moving-flow",
          path: node.id,
          direction: 1,
          count: 5,
          shape: "dot",
          size: 7,
          color: "#345d97",
          window: { start: 0, end: 180 },
          speed: [
            { frame: 0, pxPerFrame: 2 },
            { frame: 180, pxPerFrame: 4 },
          ],
        },
      ];
      if (kind === "spatial-morph") {
        node.opacity = 0;
        scene.nodes.push(
          PreparedNodeSchema.parse({
            id: "motion-matte",
            type: "rect",
            x: 400,
            y: 500,
            width: 300,
            height: 300,
            radius: 30,
            fill: "#ffffff",
          }),
        );
        scene.componentData = ComponentDataSchema.parse({
          ...scene.componentData,
          schemaVersion: "scene-components-3",
          masks: [{ target: node.id, mask: "motion-matte", invert: true }],
        });
      }
    }
    return { id: `${id}/${kind}`, scene };
  });
}

tests/helpers/composition-appearance.ts.source:
import {
  type CommerceScene,
  type StoryScene,
} from "@still-shift/scene-contract";

export function appearanceVariants<T extends CommerceScene | StoryScene>(
  id: string,
  source: T,
): { id: string; scene: T }[] {
  const selected = [
    "commerce/atom-path",
    "commerce/atom-panel",
    "component/story-leader",
    "component/story-state",
    "typography/editorial",
  ];
  if (!selected.includes(id)) return [];
  const styles =
    id === "commerce/atom-path"
      ? (["uniform", "ink", "brush"] as const)
      : (["uniform"] as const);
  return styles.map((style) => {
    const scene = structuredClone(source);
    scene.motionModel = "curves-1";
    const path = scene.nodes.find((node) => node.type === "path");
    const rect = scene.nodes.find((node) => node.type === "rect");
    const text = scene.nodes.find(
      (node) =>
        node.type === "text" &&
        (id !== "component/story-state" || node.id === "behavior__caption"),
    );
    scene.signals = [
      ...(scene.signals ?? []),
      {
        id: "appearance",
        keys: [
          { frame: 0, value: 0 },
          { frame: 100, value: 1 },
        ],
      },
    ];
    scene.drivers = [...(scene.drivers ?? [])];
    if (path?.type === "path") {
      path.lineStyle = style;
      scene.drivers.push(
        {
          target: `${path.id}.strokeWidth`,
          signal: "appearance",
          map: { scale: 14, offset: 2 },
        },
        {
          target: `${path.id}.trimStart`,
          signal: "appearance",
          map: { scale: 0.2 },
        },
        {
          target: `${path.id}.trimEnd`,
          signal: "appearance",
          map: { scale: 0.35, offset: 0.65 },
        },
        {
          target: `${path.id}.trimOffset`,
          signal: "appearance",
          map: { scale: 1.3, offset: -0.4 },
        },
      );
    }
    if (rect?.type === "rect") {
      rect.stroke = "#73472a";
      rect.lineWidth = 2;
      scene.drivers.push({
        target: `${rect.id}.strokeWidth`,
        signal: "appearance",
        map: { scale: 8, offset: 2 },
      });
    }
    if (scene.schemaVersion === "story-scene-1") {
      if (path)
        scene.recipe.moves.push({
          node: path.id,
          window: { start: 10, end: 100, easing: "in-out-cubic" },
          to: { stroke: "#b73963" },
        });
      if (rect)
        scene.recipe.moves.push({
          node: rect.id,
          window: { start: 10, end: 100, easing: "in-out-cubic" },
          to: { fill: "#345abc", stroke: "#eadaca" },
        });
      if (text)
        scene.recipe.moves.push({
          node: text.id,
          keys: [
            { frame: 0, color: "#233b32" },
            { frame: 90, color: "#cb4437", easing: "in-out-cubic" },
            { frame: 140, color: "#334499" },
          ],
        });
      if (
        id === "component/story-state" &&
        scene.componentData &&
        scene.componentData.schemaVersion !== "scene-components-1"
      )
        for (const state of scene.componentData.states)
          for (const cut of state.cuts) cut.ramp = 3;
    }
    return { id: `${id}/appearance-${style}`, scene };
  });
}

tests/helpers/composition-primitive-blur.source:
import {
  ComponentDataSchema,
  PreparedNodeSchema,
  type CommerceScene,
  type StoryScene,
} from "@still-shift/scene-contract";

export function primitiveBlurVariants<T extends CommerceScene | StoryScene>(
  id: string,
  source: T,
): { id: string; scene: T }[] {
  if (
    ![
      "component/commerce-state",
      "component/story-state",
      "commerce/atom-path",
      "typography/editorial",
    ].includes(id)
  )
    return [];
  const scene = structuredClone(source);
  scene.motionModel = "curves-1";
  scene.signals = [
    ...(scene.signals ?? []),
    {
      id: "primitiveBlur",
      keys: [
        { frame: 0, value: 0 },
        { frame: 40, value: 4 },
        { frame: 80, value: 0 },
        { frame: 120, value: 6 },
      ],
    },
  ];
  scene.drivers = [...(scene.drivers ?? [])];
  if (!id.startsWith("component/")) {
    const target = scene.nodes.find(
      (node) => node.type === (id === "commerce/atom-path" ? "path" : "text"),
    )!;
    scene.drivers.push({
      target: `${target.id}.blur`,
      signal: "primitiveBlur",
    });
    return (
      target.type === "path"
        ? (["uniform", "ink", "brush"] as const)
        : (["text"] as const)
    ).map((style) => {
      const result = structuredClone(scene);
      const node = result.nodes.find((node) => node.id === target.id)!;
      if (node.type === "path" && style !== "text") node.lineStyle = style;
      return { id: `${id}/primitive-blur-${style}`, scene: result };
    });
  }
  const group = scene.nodes.find((node) => node.id === "behavior__detail")!;
  if (group.type !== "group") throw new Error("Expected group");
  group.clip = true;
  group.opacity = 0.65;
  group.rotation = 7;
  const caption = scene.nodes.find((node) => node.id === "behavior__caption")!;
  if (caption.type !== "text") throw new Error("Expected caption");
  caption.opacity = 0.65;
  caption.container = {
    kind: "thought",
    padding: 12,
    radius: 8,
    fill: "#dce1cf",
    stroke: "#234567",
    strokeWidth: 2,
  };
  for (const node of [
    group,
    caption,
    scene.nodes.find((node) => node.id === "behavior__route")!,
  ])
    scene.drivers.push({ target: `${node.id}.blur`, signal: "primitiveBlur" });
  scene.signals.push({
    id: "childBlur",
    keys: [
      { frame: 0, value: 0 },
      { frame: 40, value: 0 },
      { frame: 60, value: 2 },
      { frame: 84, value: 0 },
    ],
  });
  scene.drivers.push({ target: "behavior__inset.blur", signal: "childBlur" });
  if (scene.componentData?.schemaVersion !== "scene-components-1")
    for (const state of scene.componentData!.states)
      for (const cut of state.cuts) cut.ramp = 3;
  const masked = structuredClone(scene);
  masked.nodes.push(
    PreparedNodeSchema.parse({
      id: "blurMask",
      type: "rect",
      x: group.x + 80,
      y: group.y,
      width: group.width / 2,
      height: group.height,
      fill: "#ffffff",
      opacity: 0.7,
      radius: 15,
    }),
  );
  masked.componentData = ComponentDataSchema.parse({
    ...masked.componentData,
    schemaVersion: "scene-components-3",
    masks: [{ target: group.id, mask: "blurMask", invert: true }],
  });
  const stacked = structuredClone(masked);
  stacked.effects = [
    {
      type: "focus-blur",
      target: group.id,
      start: 0,
      end: 150,
      radius: 2,
      endRadius: 0,
    },
  ];
  if (stacked.schemaVersion === "story-scene-1")
    stacked.effectsVersion = "effects-1";
  return [
    { id: `${id}/primitive-blur`, scene },
    { id: `${id}/primitive-blur-matte`, scene: masked },
    { id: `${id}/primitive-blur-stack`, scene: stacked },
  ];
}

tests/helpers/composition-story-componen.source:
import {
  ComponentDataSchema,
  PreparedNodeSchema,
  type StoryScene,
} from "@still-shift/scene-contract";

/** Exercise component content under the story camera and shared root masks. */
export function storyComponentVariants(id: string, source: StoryScene) {
  if (id === "component/story-state") {
    const scene = structuredClone(source);
    scene.motionModel = "curves-1";
    const caption = scene.nodes.find(
      (node) => node.id === "behavior__caption",
    )!;
    if (caption.type !== "text") throw new Error("Expected component caption");
    caption.opacity = 0.65;
    caption.container = {
      kind: "thought",
      padding: 12,
      radius: 8,
      fill: "#dce1cf",
      stroke: "#234567",
      strokeWidth: 2,
    };
    const data = scene.componentData!;
    if (data.schemaVersion === "scene-components-1")
      throw new Error("Expected states");
    for (const schedule of data.states)
      for (const cut of schedule.cuts) cut.ramp = 3;
    return [{ id: `${id}/blended-container`, scene }];
  }
  if (id !== "component/story-leader") return [];
  return ["flow", "flow-target-matte", "flow-target-inverted"].map((kind) => {
    const scene = structuredClone(source);
    const path = scene.nodes.find((node) => node.id === "annotation__line")!;
    path.opacity = 0.65;
    scene.flows = [
      {
        id: "annotation-flow",
        path: path.id,
        direction: 1,
        count: 3,
        shape: "dot",
        size: 5,
        color: "#c44526",
        window: { start: 0, end: scene.frameCount - 1 },
        speed: [
          { frame: 0, pxPerFrame: 2 },
          { frame: scene.frameCount - 1, pxPerFrame: 4 },
        ],
      },
    ];
    const masks = [];
    if (kind !== "flow") {
      scene.nodes.push(
        PreparedNodeSchema.parse({
          id: "flow-matte",
          type: "rect",
          x: 300,
          y: 130,
          width: 900,
          height: 500,
          radius: 30,
          fill: "#ffffff",
          opacity: 0.6,
        }),
      );
      masks.push({
        target: path.id,
        mask: "flow-matte",
        invert: kind === "flow-target-inverted",
      });
    }
    if (kind === "flow-target-inverted") path.opacity = 0;
    scene.componentData = ComponentDataSchema.parse({
      ...scene.componentData,
      schemaVersion: "scene-components-3",
      masks,
      visibility: [
        {
          id: "flow-visibility",
          target: path.id,
          window: { start: 10, end: 150 },
        },
      ],
    });
    return { id: `${id}/${kind}`, scene };
  });
}

