import { execFileSync } from "node:child_process";
import { readFile, writeFile } from "node:fs/promises";
import { resolve, dirname } from "node:path";
import { createHash } from "node:crypto";
import {
  compileCommerceComposition,
  compileStoryComposition,
  readStoryPassage,
} from "@still-shift/animation-engine";
import {
  storyToComposition,
  evaluateComp,
  buildRenderGraph,
} from "@still-shift/renderer-core";
import {
  CommerceSceneSchema,
  StorySceneSchema,
} from "@still-shift/scene-contract";
import { commerceEffectVariants } from "../../../tests/helpers/composition-effects.ts";
import { commerceExposureVariants } from "../../../tests/helpers/composition-commerce-exposure.ts";
import { commerceTextVariants } from "../../../tests/helpers/composition-commerce-text.ts";
import { commerceGeometryVariants } from "../../../tests/helpers/composition-commerce-geometry.ts";
import { commerceMaskVariants } from "../../../tests/helpers/composition-commerce-masks.ts";
import { commerceLayoutVariants } from "../../../tests/helpers/composition-commerce-layout.ts";
import { commerceTextStateVariants } from "../../../tests/helpers/composition-commerce-text-states.ts";
import { motionPathVariants } from "../../../tests/helpers/composition-motion-path.ts";
import { appearanceVariants } from "../../../tests/helpers/composition-appearance.ts";
import { primitiveBlurVariants } from "../../../tests/helpers/composition-primitive-blur.ts";
import { storyComponentVariants } from "../../../tests/helpers/composition-story-components.ts";
import { storyEffectVariants } from "../../../tests/helpers/composition-story-effects.ts";
import {
  numericTypographyVariants,
  typographyVariants,
} from "../../../tests/helpers/composition-typography.ts";
const root = resolve(import.meta.dirname, "../../..");
const digest = (s: string) => createHash("sha256").update(s).digest("hex");
const preparation: any = {
  status: "in-progress",
  date: new Date().toISOString(),
  dependencySha256: {},
};
try {
  const dependencyPaths = execFileSync(
    "git",
    [
      "ls-files",
      "packages/renderer-core/src",
      "packages/animation-engine/src",
      "packages/scene-contract/src",
      "tests/helpers",
    ],
    { cwd: root, encoding: "utf8" },
  )
    .trim()
    .split("\n")
    .filter((path) => path.endsWith(".ts"));
  dependencyPaths.push(
    "docs/composition-ce6p-family-audit.json",
    "tests/visual/composition-baselines/fixtures.json",
    "package.json",
    "pnpm-lock.yaml",
    "packages/renderer-core/src/composition/render/webgl-disjoint-paints.ts",
  );
  for (const path of dependencyPaths)
    preparation.dependencySha256[path] = digest(
      await readFile(resolve(root, path), "utf8"),
    );
  const payloads: any[] = [];
  const audit = JSON.parse(
    await readFile(
      resolve(root, "docs/composition-ce6p-family-audit.json"),
      "utf8",
    ),
  );
  const inventory = JSON.parse(
    await readFile(
      resolve(root, "tests/visual/composition-baselines/fixtures.json"),
      "utf8",
    ),
  ).fixtures;
  const failures = Object.entries(audit.families).flatMap(
    ([family, value]: [string, any]) =>
      value.items
        .filter((item: any) => item.ratio > 1.25)
        .map((item: any) => ({
          family,
          ...item,
          original: value.originalFailureStatus.some(
            (x: any) => x.id === item.id,
          ),
        })),
  );
  const selected = inventory.filter((entry: any) =>
    failures.some(
      (f: any) => f.id === entry.id || f.id.startsWith(entry.id + "/"),
    ),
  );
  const generated = new Map();
  const record: any = {
    method:
      "Untimed routing map for all 119 retained timing failures. Actual adapter variant generators, compiled composition, evaluator and render graph at selected frames. Graph operations identify possible paths; this is not measured GPU cost, complete timeline coverage or timing closure.",
    sourceSha256: {},
    items: [],
  };
  for (const entry of selected) {
    const path = resolve(root, entry.path);
    const source = await readFile(path, "utf8");
    record.sourceSha256[entry.path] = digest(source);
    const raw = JSON.parse(source);
    const bases =
      entry.kind === "passage"
        ? (await readStoryPassage(path)).beats.map((beat) => ({
            id: entry.id + "/" + beat.id,
            scene: beat.scene,
          }))
        : [{ id: entry.id, scene: raw }];
    for (const item of bases) {
      const commerce = item.scene.schemaVersion === "commerce-scene-1";
      const scene = commerce
        ? CommerceSceneSchema.parse(item.scene)
        : StorySceneSchema.parse(item.scene);
      const variants =
        entry.family === "typography"
          ? [
              ...typographyVariants(scene).map((v) => ({
                ...v,
                id: item.id + "/" + v.id,
              })),
              ...numericTypographyVariants(scene).map((v) => ({
                ...v,
                id: item.id + "/" + v.id,
              })),
              ...appearanceVariants(item.id, scene),
              ...primitiveBlurVariants(item.id, scene),
              ...(commerce ? commerceExposureVariants(item.id, scene) : []),
            ]
          : commerce
            ? [
                ...commerceTextVariants(item.id, scene),
                ...commerceGeometryVariants(item.id, scene),
                ...commerceMaskVariants(item.id, scene),
                ...commerceLayoutVariants(item.id, scene),
                ...commerceTextStateVariants(item.id, scene),
                ...motionPathVariants(item.id, scene),
                ...appearanceVariants(item.id, scene),
                ...primitiveBlurVariants(item.id, scene),
                ...commerceEffectVariants(item.id, scene),
                ...commerceExposureVariants(item.id, scene),
              ]
            : [
                ...storyComponentVariants(item.id, scene),
                ...motionPathVariants(item.id, scene),
                ...appearanceVariants(item.id, scene),
                ...storyEffectVariants(item.id, scene),
                ...primitiveBlurVariants(item.id, scene),
              ];
      for (const v of [{ id: item.id, scene }, ...variants])
        if (failures.some((f) => f.id === v.id))
          generated.set(v.id, { ...v, path, family: entry.family });
    }
  }
  const walk = (ops: any[], counts: Record<string, number>) => {
    for (const op of ops) {
      const key =
        op.kind === "draw"
          ? "draw/" +
            op.content.type +
            (op.content.type === "provider"
              ? "/" + op.content.layer.provider
              : "")
          : op.kind;
      counts[key] = (counts[key] ?? 0) + 1;
      for (const effect of op.effects ?? [])
        counts["effect/" + effect.effect] =
          (counts["effect/" + effect.effect] ?? 0) + 1;
      if (op.masks?.length)
        counts.masks = (counts.masks ?? 0) + op.masks.length;
      if (op.matte) {
        counts["matte/" + op.matte.mode] =
          (counts["matte/" + op.matte.mode] ?? 0) + 1;
        walk(op.matte.ops, counts);
      }
      if (op.ops) walk(op.ops, counts);
      if (op.content?.surface) walk(op.content.surface.ops, counts);
    }
  };
  for (const f of failures) {
    const item = generated.get(f.id);
    if (!item) throw Error("Missing actual variant " + f.id);
    const commerce = item.scene.schemaVersion === "commerce-scene-1";
    const comp = commerce
      ? await compileCommerceComposition(item.scene, dirname(item.path))
      : item.family === "typography"
        ? await compileStoryComposition(item.scene, dirname(item.path))
        : storyToComposition(item.scene);
    const frames = [];
    for (const frame of [...new Set([0, 24, 96, comp.frameCount - 1])].filter(
      (f) => f < comp.frameCount,
    )) {
      const graph = buildRenderGraph(comp, evaluateComp(comp, frame));
      const counts = {};
      walk(graph.root.ops, counts);
      frames.push({ frame, counts });
    }
    payloads.push({
      id: f.id,
      family: f.family,
      originalFailure: f.original,
      recordedRatio: f.ratio,
      composition: comp,
      urls: Object.fromEntries(
        comp.assets.map((a: any) => [
          a.id,
          "/@fs" + resolve(dirname(item.path), a.path),
        ]),
      ),
      sourcePath: item.path.slice(root.length + 1),
      sceneSha256: digest(JSON.stringify(item.scene)),
      compositionSha256: digest(JSON.stringify(comp)),
    });
    record.items.push({
      id: f.id,
      family: f.family,
      originalFailure: f.original,
      recordedRatio: f.ratio,
      sourcePath: item.path.slice(root.length + 1),
      suppliedSceneSha256: digest(JSON.stringify(item.scene)),
      compositionSha256: digest(JSON.stringify(comp)),
      size: [comp.width, comp.height],
      frameCount: comp.frameCount,
      frames,
    });
  }
  record.coverage = {
    currentFailures: failures.length,
    mapped: record.items.length,
    originalFailures: record.items.filter((i: any) => i.originalFailure).length,
  };
  for (const [path, hash] of Object.entries(preparation.dependencySha256))
    if (digest(await readFile(resolve(root, path), "utf8")) !== hash)
      throw Error("Preparation dependency changed: " + path);
  preparation.status = "complete";
  const artifact = {
    preparation,
    method:
      "Actual adapter-generated failure workloads for untimed GPU operation and clear-backdrop eligibility traces. This preparation does not render or measure elapsed time.",
    preparerSha256: digest(await readFile(import.meta.filename, "utf8")),
    fixtureSha256: record.sourceSha256,
    coverage: record.coverage,
    payloads,
  };
  await writeFile(
    resolve(
      root,
      "benchmarks/results/composition-ce6p/failure-coverage-payloads.json",
    ),
    JSON.stringify(artifact, null, 2) + "\n",
  );
  console.log(JSON.stringify(record.coverage));
} catch (error) {
  preparation.status = "failed";
  preparation.error = String(error);
  await writeFile(
    resolve(
      root,
      `benchmarks/results/composition-ce6p/failure-coverage-preparation-failed-${Date.now()}.json`,
    ),
    JSON.stringify(preparation, null, 2) + "\n",
  );
  throw error;
}

